<template>
  <div class="vote_list_box">
    <el-container>
      <el-header>

        <el-row>
          <el-col :span="4">
            <el-button type="primary" icon="el-icon-plus" @click="add_vote">添加投票</el-button>
          </el-col>
          <el-col :span="20">
            <span>筛选：</span>
            <el-input class="search_width" v-model="search_val" size="small" maxlength="10" placeholder="请输入搜索内容"></el-input>
            <el-select class="search_width" v-model="search_type" placeholder="请选择" size="small">
              <el-option
                v-for="item in options"
                :key="item.value"
                :label="item.label"
                :value="item.value">
              </el-option>
            </el-select>
            &nbsp;&nbsp;&nbsp;&nbsp;
            <span>日期筛选：</span>
            <el-date-picker
              size="small"
              v-model="date"
              value-format="yyyy/MM/dd"
              type="daterange"
              range-separator="至"
              start-placeholder="开始日期"
              end-placeholder="结束日期">
            </el-date-picker>
            &nbsp;&nbsp;&nbsp;&nbsp;
            <el-button type="primary" icon="el-icon-search" @click="search_list">查询</el-button>
          </el-col>
        </el-row>

      </el-header>
      <el-main class="table_box" v-if="vote_data">
        <el-table
          class="list_table"
          :data="vote_data"
          style="width:100%"
          :row-class-name="tableRowClassName"
          :height="550">
          <el-table-column
            prop="vote_id"
            label="ID"
            min-width="40">
          </el-table-column>
          <el-table-column
            prop="vote_title"
            label="标题"
            min-width="120">
          </el-table-column>
          <el-table-column
            prop="start_time_txt"
            label="开始时间"
            min-width="150">
          </el-table-column>
          <el-table-column
            prop="end_time_txt"
            label="结束时间"
            min-width="150">
          </el-table-column>
          <el-table-column
            prop="vote_number"
            label="参与人次"
            min-width="80">
          </el-table-column>
          <el-table-column
            prop="vote_sort"
            label="排序值"
            min-width="50">
          </el-table-column>
          <el-table-column
            prop="status_txt"
            label="状态"
            min-width="150">
          </el-table-column>
          <el-table-column
            fixed="right"
            label="操作"
            width="150">
            <template slot-scope="scope">
              <el-button type="text" size="small" @click.native.prevent="editRow(scope.$index, vote_data)">编辑</el-button>
              <el-button
                @click.native.prevent="deleteRow(scope.$index, vote_data)"
                type="text"
                class="Danger"
                size="small">
                删除
              </el-button>
              <el-button type="text" size="small" @click.native.prevent="vote_statistics(scope.$index, vote_data)">收集结果</el-button>
            </template>
          </el-table-column>
        </el-table>
      </el-main>

      <el-footer>
        <div v-show="total_page>0" class="page_msg">
          <el-pagination
            background
            layout="prev, pager, next"
            :page-count="total_page"
            :current-page="page"
            @current-change="current_change"
          >
          </el-pagination>
        </div>
      </el-footer>
    </el-container>

  </div>

</template>

<script>
  export default {
    name:'vote_list',
    data() {
      return {
        page: 1,
        total_page: 20,
        pagerCount: 10,
        date: '',
        options: [{
          value: 'vote_id',
          label: '投票ID'
        }, {
          value: 'vote_title',
          label: '投票标题'
        }],
        search_val: '',
        search_type: 'vote_id',
        vote_data: []
      }
    },
    created () {
      var _this = this
      this.getVoteList();
    },
    methods: {
      vote_statistics: function(index, rows) {
        let msg = rows[index];
        this.$router.replace({ path: '/vote_statistics', query: { vote_id: msg.vote_id }});
      },
      // 请求投票数据
      async getVoteList () {
        let _this = this
        let param = {
          page: this.page,
          search_val: this.search_val,
          search_type: this.search_type,
        }
        if (this.date) {
          let start_time = this.date[0];
          let end_time = this.date[1];
          param.start_time = start_time;
          param.end_time = end_time;
        }
          console.log('param',param);
        let res = await this.$api.voteList(param);
        if (!res) return;
        this.total_page = res.total_page;
        this.vote_data = res.list;
      },
      // 删除投票
      async delVote (vote_id, rows, index, _this) {
        let param = {
          vote_id: vote_id,
        }
        let res = await this.$api.delVote(param);
        console.log(`删除投票: `, res);
        if (res) {
          rows.splice(index, 1);
          _this.$message({
            type: 'success',
            message: '删除成功!'
          });
        } else if (res.errorMsg) {
          _this.$message({
            type: 'info',
            message: res.errorMsg
          });
        }
        return res;
      },
      search_list() {
        console.log('搜索');
        console.log('search_type',this.search_type);
        console.log('search_val',this.search_val);
        this.page = 1;
        this.getVoteList();
      },
      current_change(val) {
        this.page = val;
        this.getVoteList();
        console.log(`当前页: ${val}`);
        console.log(`当前页1: `,this.page);
      },
      tableRowClassName({row, rowIndex}) {
        if (row['status'] === '0') {
          return 'warning_row';
        }
        return '';
      },
      deleteRow(index, rows) {
        let _this = this
        this.$confirm('此操作将永久删除该投票, 是否继续?', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        }).then(() => {
          let vote_id = rows[index]['vote_id'];
          this.delVote(vote_id, rows, index, _this);
        }).catch(() => {
          _this.$message({
            type: 'info',
            message: '已取消删除'
          });
        });
      },
      editRow(index,rows) {
        let msg = rows[index];
        this.$router.replace({ path: '/add_vote', query: { vote_id: msg.vote_id }});
      },
      add_vote() {
        this.$router.replace({ path: '/add_vote'});
      }
    }
  }
</script>
<style>
  .vote_list_box .el-table__row.warning_row {
    background: #E4E7ED;
  }
</style>
<style scoped>
  .vote_list_box {
    padding: 20px 10px;
  }
  .vote_list_box .list_table {
    border: 1px solid #EBEEF5;
  }
  .vote_list_box .table_box {
    width: 100%;
  }
  .vote_list_box .Danger {
    color: #F56C6C;
  }
  .vote_list_box .search_width {
    width: 150px;
  }
  .vote_list_box .page_msg {
    text-align: center;
  }
</style>
